stock=12
lost=0
stockout_times=[]
for e in events:
    if e['kind']=='receipt':
        stock += e['quantity']
    else:
        unmet=max(e['quantity']-stock,0)
        if unmet>0: stockout_times.append(e['event_time'])
        lost += unmet
        stock -= min(stock,e['quantity'])
